    def clamp(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def as_list(v):
        return v if isinstance(v, list) else []

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp(b[0] - a[0]), clamp(b[1] - a[1])]

    def step_away(a, b):
        return [clamp(a[0] - b[0]), clamp(a[1] - b[1])]

    def within(p, w, h):
        return w > 0 and h > 0 and 0 <= p[0] < w and 0 <= p[1] < h

    def best_by_score(points, score_fn):
        best = None
        best_score = None
        for p in points:
            s = score_fn(p)
            if best is None or s < best_score:
                best = p
                best_score = s
        return best

    env = observation.get("environment_name", "") or ""
    role = observation.get("self_role", "") or ""
    sx, sy = pair(observation.get("self_position"))
    ox, oy = pair(observation.get("opponent_position"), (sx, sy))
    me = (sx, sy)
    opp = (ox, oy)
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    resources = []
    for item in as_list(observation.get("resources")):
        p = pair(item, None)
        if p is not None:
            resources.append(p)

    unclaimed = []
    for item in as_list(observation.get("unclaimed_cells")):
