        if p is not None:
            opp_terr.append(p)

    own_terr = []
    for item in as_list(observation.get("self_territory")):
        p = pair(item, None)
        if p is not None:
            own_terr.append(p)

    # Pursuit / evasion
    if env == "pursuit_evasion":
        if role == "pursuer":
            target = opp
            if w and h and within(opp, w, h):
                return step_toward(me, target)
            return step_toward(me, target)

        # Evader: maximize distance from pursuer, prefer corners farthest away.
        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-9, -9), (-9, 9), (9, -9), (9, 9)]
