            )
            return step_toward(me, target)

        if w and h:
            return step_toward(me, ((w - 1) // 2, (h - 1) // 2))
        return [0, 0]

    # Resource collection / denial
    if resources:
        target = best_by_score(
            resources,
            lambda p: manhattan(me, p) + max(0, 2 - manhattan(opp, p)) * 2
        )
        return step_toward(me, target)

    # If opponent is nearby, pressure/avoid depending on apparent role.
    if env == "resource_collection":
        if role == "collector":
            if own_terr:
                target = best_by_score(own_terr, lambda p: manhattan(me, p))
                return step_toward(me, target)
            if opp != me:
                return step_away(me, opp)
        else:
            if opp != me:
                return step_toward(me, opp)

    # Generic fallback
    if opp != me:
        return step_toward(me, opp)

    if w and h:
        return step_toward(me, ((w - 1) // 2, (h - 1) // 2))

